/*********** inlocuieste cele 5 entitati predefinite in XML cu referintele la entitate coresponzatoare
************ & (si - ampersand ) devine &amp;
************ < (mai mic decat - less-than sign) devine &lt;
************ > (mai mare decat - greater-than sign) devine &gt;
************ " (ghilimele - double quotation mark) devine &quot;
************ ' (apostrof - apostrophe) devine &apos;
************  ATENTIE: prima entitate care trebuie inlocuita cu referinta este &
*************/
function schEnt(Ref){
	var sir = "";
	sir = Ref.replace(/[&]/g,"&amp;"); 
	sir = sir.replace(/[<]/g,"&lt;");
	sir = sir.replace(/[>]/g,"&gt;"); 
	sir = sir.replace(/["]/g,"&quot;"); 
	sir = sir.replace(/[']/g,"&apos;");
	return sir; 
}// eof schEnt
